SourceCode.Declaration:
/// <summary>
/// Opens the Copy setup dialog. The selected environment is the source.
/// </summary>
public final class BDRSetupCopyController extends SysOperationServiceController
{
}

Method.Source:
protected void new()
{
    super(classStr(BDRSetupCopyService), methodStr(BDRSetupCopyService, process), SysOperationExecutionMode::Synchronous);
}

public static BDRSetupCopyController construct()
{
    return new BDRSetupCopyController();
}

    public static void main(Args _args)
    {
        BDRSetupCopyController controller = BDRSetupCopyController::construct();

        // Start with an empty dialog; a remembered target from the last copy is easy to miss.
        controller.parmLoadFromSysLastValue(false);

        BDRSetupCopyContract contract = controller.getDataContractObject() as BDRSetupCopyContract;

        if (!_args || !_args.record() || _args.record().TableId != tableNum(BDREnvironment))
        {
            throw error("@BDR:ErrOpenFromEnvironment");
        }

        BDREnvironment environment = _args.record();
        contract.parmSourceEnvironmentId(environment.EnvironmentId);
        contract.parmTargetEnvironmentId('');

        controller.parmArgs(_args);
        controller.parmDialogCaption(strFmt('%1: %2', "@BDR:CopySetup", environment.EnvironmentId));
        controller.startOperation();

        if (_args && _args.caller() is FormRun)
        {
            FormRun caller = _args.caller();
            caller.dataSource(1).research(true);
        }
    }
